mapper.insert:

insert into setmeal (tenant_id, category_id, name, price, status, description, image,
                     create_time, update_time, create_user, update_user)
select #{scopeTenant}, #{categoryId}, #{name}, #{price}, #{status}, #{description}, #{image},
        #{createTime}, #{updateTime}, #{createUser}, #{updateUser}
from category c where c.id = #{categoryId} and c.tenant_id = #{scopeTenant}

mapper.select:

select s.*, c.name as categoryName
from setmeal s
left join category c on s.category_id = c.id and c.tenant_id = s.tenant_id

    s.tenant_id = #{scopeTenant}

        and s.name like CONCAT('%', #{name}, '%')


        and s.category_id = #{categoryId}


        and s.status = #{status}


order by s.create_time desc, s.id desc

mapper.delete:

delete from setmeal where tenant_id = #{scopeTenant} and id in

    #{id}


and (select count(*) from (select id, tenant_id from setmeal group by id, tenant_id) owned where owned.tenant_id = #{scopeTenant} and owned.id in
#{requestedId}) = #{requestedCount}

mapper.select:

select * from setmeal

    tenant_id = #{scopeTenant}

        and name like concat('%',#{name},'%')


        and category_id = #{categoryId}


        and status = #{status}
